import json
import os
import platform

from thirdparty._internal.output import Output
from thirdparty._internal.util.files import save, load
from thirdparty.build import build_jobs

from thirdparty.cmake.toolchain.blocks import GenericSystemBlock
from thirdparty.cmake.utils import is_multi_configuration
from thirdparty.errors import RecipeException
from thirdparty.microsoft import is_msvc

from typing import Any, cast
from thirdparty.recipe import RecipeBase


def write_cmake_presets(
    recipe: RecipeBase,
    toolchain_file: Any,
    generator: Any,
    cache_variables: Any,
    user_presets_path: Any = None,
    preset_prefix: Any = None,
    buildenv: Any = None,
    runenv: Any = None,
    cmake_executable: Any = None,
    absolute_paths: Any = None):
    preset_path, preset_data = _CMakePresets.generate(
        recipe, toolchain_file, generator, cache_variables, preset_prefix, buildenv, runenv, cmake_executable, absolute_paths)
    _IncludingPresets.generate(
        recipe, preset_path, user_presets_path, preset_prefix, preset_data, absolute_paths)


class _CMakePresets:
    """ Recipe generated main CMakePresets.json inside the generators_folder
    """

    @staticmethod
    def generate(
        recipe: RecipeBase, toolchain_file: Any, generator: Any, cache_variables: Any, preset_prefix: Any, buildenv: Any, runenv: Any, cmake_executable: Any, absolute_paths: Any) -> tuple[str, dict[str, Any]]:
        toolchain_file = os.path.abspath(os.path.join(recipe.folders.generators, toolchain_file))
        if not absolute_paths:
            try:  # Make it relative to the build dir if possible
                toolchain_file = os.path.relpath(toolchain_file, recipe.folders.build)
            except ValueError:
                pass
        cache_variables = cache_variables or {}
        if platform.system() == "Windows" and generator == "MinGW Makefiles":
            if "CMAKE_SH" not in cache_variables:
                cache_variables["CMAKE_SH"] = "CMAKE_SH-NOTFOUND"

        cmake_make_program: Any = recipe.conf.tools.gnu.make_program or cache_variables.get("CMAKE_MAKE_PROGRAM")
        if cmake_make_program:
            cmake_make_program = cmake_make_program.replace("\\", "/")
            cache_variables["CMAKE_MAKE_PROGRAM"] = cmake_make_program

        if "CMAKE_POLICY_DEFAULT_CMP0091" not in cache_variables:
            cache_variables["CMAKE_POLICY_DEFAULT_CMP0091"] = "NEW"

        if "BUILD_TESTING" not in cache_variables:
            if recipe.conf.tools.build.skip_test:
                cache_variables["BUILD_TESTING"] = "OFF"

        preset_path = os.path.join(recipe.folders.generators, "CMakePresets.json")
        multiconfig = is_multi_configuration(generator)
        if os.path.exists(preset_path):
            data = json.loads(load(preset_path))
            if "recipe" not in data.get("vendor", {}):
                # The file is not ours, we cannot overwrite it
                raise RecipeException(
                    "Existing CMakePresets.json not generated by Recipe cannot be "
                    "overwritten.\nUse --output-folder or define a 'layout' to "
                    "avoid collision with your CMakePresets.json")
        if os.path.exists(preset_path) and multiconfig:
            data = json.loads(load(preset_path))
            build_preset = _CMakePresets._build_preset_fields(recipe, multiconfig, preset_prefix)
            test_preset = _CMakePresets._test_preset_fields(
                recipe, multiconfig, preset_prefix, runenv)
            _CMakePresets._insert_preset(data, "buildPresets", build_preset)
            _CMakePresets._insert_preset(data, "testPresets", test_preset)
            configure_preset = _CMakePresets._configure_preset(
                recipe, generator, cache_variables, toolchain_file, multiconfig, preset_prefix, buildenv, cmake_executable)
            # Recipe generated presets should have only 1 configurePreset, no more, overwrite it
            data["configurePresets"] = [configure_preset]
        else:
            data = _CMakePresets._contents(
                recipe, toolchain_file, cache_variables, generator, preset_prefix, buildenv, runenv, cmake_executable)

        preset_content = json.dumps(data, indent=4)
        save(preset_path, preset_content)
        Output(str(recipe)).info(f"CMakeToolchain generated: {preset_path}")
        return preset_path, data

    @staticmethod
    def _insert_preset(data: Any, preset_type: str, preset: Any):
        presets = data.setdefault(preset_type, [])
        preset_name = preset["name"]
        positions = [index for index, p in enumerate(presets) if p["name"] == preset_name]
        if positions:
            data[preset_type][positions[0]] = preset
        else:
            data[preset_type].append(preset)

    @staticmethod
    def _contents(
        recipe: RecipeBase, toolchain_file: Any, cache_variables: Any, generator: Any, preset_prefix: Any, buildenv: Any, runenv: Any, cmake_executable: Any) -> dict[str, Any]:
        """
        Contents for the CMakePresets.json
        It uses schema version 3 unless it is forced to 2
        """
        multiconfig = is_multi_configuration(generator)
        conf = _CMakePresets._configure_preset(
            recipe, generator, cache_variables, toolchain_file, multiconfig, preset_prefix, buildenv, cmake_executable)
        build = _CMakePresets._build_preset_fields(recipe, multiconfig, preset_prefix)
        test = _CMakePresets._test_preset_fields(recipe, multiconfig, preset_prefix, runenv)
        ret: dict[str, Any] = {
            "version": 3, "vendor": {"recipe": {}}, "cmakeMinimumRequired": {"major": 3, "minor": 15, "patch": 0}, "configurePresets": [conf], "buildPresets": [build], "testPresets": [test],
        }
        return ret

    @staticmethod
    def _configure_preset(
        recipe: RecipeBase, generator: Any, cache_variables: Any, toolchain_file: Any, multiconfig: bool, preset_prefix: Any, buildenv: Any, cmake_executable: Any) -> dict[str, Any]:
        build_type = recipe.settings.build_type
        name = _CMakePresets._configure_preset_name(recipe, multiconfig)
        if preset_prefix:
            name = f"{preset_prefix}-{name}"
        if not multiconfig and build_type:
            cache_variables["CMAKE_BUILD_TYPE"] = build_type
        ret: dict[str, Any] = {
            "name": name, "displayName": f"'{name}' config", "description": f"'{name}' configure using '{generator}' generator", "generator": generator, "cacheVariables": cache_variables,
        }

        if buildenv:
            ret["environment"] = buildenv

        if cmake_executable:
            ret["cmakeExecutable"] = cmake_executable

        if is_msvc(recipe):
            # We can force the generator Visual even if it is Ninja, to define the toolset
            toolset = GenericSystemBlock.get_toolset("Visual", recipe)
            # It seems "external" strategy is enough, as it is defined by toolchain
            if toolset:
                ret["toolset"] = {
                    "value": toolset, "strategy": "external",
                }
            arch = GenericSystemBlock.get_generator_platform("Visual", recipe)
            # https://learn.microsoft.com/en-us/cpp/build/cmake-presets-vs
            if generator and "Ninja" in generator and arch == "Win32":
                arch = "x86"  # for command line, it is not Win32, it is x86
            if arch:
                ret["architecture"] = {
                    "value": arch, "strategy": "external",
                }

        # Second attempt at upstream issue 13136
        # for cmake-tools to activate environment. Similar to CompilersBlock
        # Only for cl/clang-cl, other compilers such clang can be breaking (Android)
        compilers_by_conf = recipe.conf.tools.build.compiler_executables
        compiler = recipe.settings.compiler
        default_cl = "cl" if compiler == "msvc" and "Ninja" in str(generator) else None
        for lang in ("c", "cpp"):
            comp: Any = compilers_by_conf.get(lang, default_cl)
            if comp and os.path.basename(comp) in ("cl", "cl.exe", "clang-cl", "clang-cl.exe"):
                lang = {"c": "C", "cpp": "CXX"}[lang]
                ret["cacheVariables"][f"CMAKE_{lang}_COMPILER"] = comp.replace("\\", "/")

        ret["toolchainFile"] = toolchain_file
        if recipe.folders.build:
            # If we are installing a ref: "recipe install <ref>", we don't have build_folder, because
            # we don't even have a recipe with a `layout()` to determine the build folder.
            # If we install a local recipe "recipe install ." with a layout(), it will be available
            ret["binaryDir"] = recipe.folders.build.as_posix()

        return ret

    @staticmethod
    def _common_preset_fields(recipe: RecipeBase, multiconfig: bool, preset_prefix: Any) -> dict[str, Any]:
        build_type = recipe.settings.build_type
        configure_preset_name = _CMakePresets._configure_preset_name(recipe, multiconfig)
        build_preset_name = _CMakePresets._build_and_test_preset_name(recipe)
        if preset_prefix:
            configure_preset_name = f"{preset_prefix}-{configure_preset_name}"
            build_preset_name = f"{preset_prefix}-{build_preset_name}"
        ret = {"name": build_preset_name, "configurePreset": configure_preset_name}
        if multiconfig:
            ret["configuration"] = build_type
        return ret

    @staticmethod
    def _build_preset_fields(recipe: RecipeBase, multiconfig: bool, preset_prefix: Any) -> dict[str, Any]:
        ret = _CMakePresets._common_preset_fields(recipe, multiconfig, preset_prefix)
        build_preset_jobs = build_jobs(recipe)
        if build_preset_jobs:
            ret["jobs"] = build_preset_jobs
        return ret

    @staticmethod
    def _test_preset_fields(
        recipe: RecipeBase,
        multiconfig: bool,
        preset_prefix: Any,
        runenv: Any) -> dict[str, Any]:
        ret = _CMakePresets._common_preset_fields(recipe, multiconfig, preset_prefix)
        build_preset_jobs = build_jobs(recipe)
        if build_preset_jobs:
            ret.setdefault("execution", {})["jobs"] = build_preset_jobs
        if runenv:
            ret["environment"] = runenv
        return ret

    @staticmethod
    def _build_and_test_preset_name(recipe: RecipeBase) -> str:
        build_type = recipe.settings.build_type
        return build_type.lower() if build_type else "default"

    @staticmethod
    def _configure_preset_name(recipe: RecipeBase, multiconfig: bool) -> str:
        build_type = recipe.settings.build_type
        if multiconfig or not build_type:
            return "default"
        return str(build_type).lower()


class _IncludingPresets:
    """
    CMakeUserPresets or RecipePresets.json that include the main generated CMakePresets
    """

    @staticmethod
    def generate(
        recipe: RecipeBase, preset_path: Any, user_presets_path: Any, preset_prefix: Any, preset_data: Any, absolute_paths: Any):
        if not user_presets_path:
            return

        # If generators folder is the same as source folder, do not create the user presets
        # we already have the CMakePresets.json right there
        if not (recipe.folders.source and recipe.folders.source != recipe.folders.generators):
            return

        is_default = user_presets_path == "CMakeUserPresets.json"
        user_presets_path = os.path.join(recipe.folders.source, user_presets_path)
        if os.path.isdir(user_presets_path):  # Allows user to specify only the folder
            output_dir = user_presets_path
            user_presets_path = os.path.join(user_presets_path, "CMakeUserPresets.json")
        else:
            output_dir = os.path.dirname(user_presets_path)

        if is_default and not os.path.exists(os.path.join(output_dir, "CMakeLists.txt")):
            return

        # It uses schema version 4 unless it is forced to 2
        inherited_user = {}
        if os.path.basename(user_presets_path) != "CMakeUserPresets.json":
            inherited_user = _IncludingPresets._collect_user_inherits(output_dir, preset_prefix)

        if not os.path.exists(user_presets_path):
            recipe_vendor: dict[str, Any] = {}
            data: Any = {
                "version": 4, "vendor": {"recipe": recipe_vendor},
            }
        else:
            data = json.loads(load(user_presets_path))
            if "recipe" not in data.get("vendor", {}):
                # The file is not ours, we cannot overwrite it
                return

        if not absolute_paths:
            try:  # Make it relative to the CMakeUserPresets.json if possible
                rel_path = cast(str, os.path.relpath(preset_path, output_dir))
                # If we don't normalize, path will be removed in Linux shared folders
                # upstream issue 18434
                preset_path = rel_path.replace("\\", "/")
            except ValueError:
                pass
        data = _IncludingPresets._append_user_preset_path(data, preset_path, output_dir)

        if inherited_user:
            data = _IncludingPresets._update_stubs(data, inherited_user, output_dir, absolute_paths)

        data = json.dumps(data, indent=4)
        Output(str(recipe)).info(f"CMakeToolchain generated: {user_presets_path}")
        save(user_presets_path, data)

    @staticmethod
    def _update_stubs(
        data: Any,
        inherited_user: Any,
        output_dir: str,
        absolute_paths: Any) -> dict[str, Any]:
        """
        Set configurePresets/buildPresets/testPresets to stubs for recipe-* presets
        that the user inherits but that don't have a real preset of the same type in the includes.
        """
        real_preset_names_by_type: dict[str, set[Any]] = {
            "configurePresets": set(), "buildPresets": set(), "testPresets": set(),
        }
        for inc in data.get("include", []):
            inc_path = os.path.join(output_dir, inc) if not absolute_paths else inc
            assert os.path.exists(inc_path), f"Presets include must point to an existing file: '{inc_path}'"
            try:
                inc_json = json.loads(load(inc_path))
            except Exception:
                continue
            for preset_type in ("configurePresets", "buildPresets", "testPresets"):
                for p in inc_json.get(preset_type, []):
                    name = p.get("name")
                    if name:
                        real_preset_names_by_type[preset_type].add(name)

        for preset_type in ("configurePresets", "buildPresets", "testPresets"):
            real_names = real_preset_names_by_type[preset_type]
            stubs: list[Any] = []
            for name in inherited_user.get(preset_type, []):
                if name not in real_names:
                    stub = {"name": name}
                    if preset_type in ("buildPresets", "testPresets"):
                        stub["configurePreset"] = name
                    stubs.append(stub)
            data[preset_type] = stubs

        return data

    @staticmethod
    def _collect_user_inherits(output_dir: str, preset_prefix: Any) -> dict[str, Any]:
        # Collect all the existing targets in the user files, to create empty recipe- presets
        # so things doesn't break for multi-platform, when inherits don't exist
        collected_targets: dict[str, list[Any]] = {}
        types = "configurePresets", "buildPresets", "testPresets"
        for file in ("CMakePresets.json", "CMakeUserPresets.json"):
            user_file = os.path.join(output_dir, file)
            if os.path.exists(user_file):
                user_json = json.loads(load(user_file))
                for preset_type in types:
                    for preset in user_json.get(preset_type, []):
                        inherits = preset.get("inherits", [])
                        if isinstance(inherits, str):
                            inherits = [inherits]
                        inherits = [i for i in inherits if i.startswith(preset_prefix)]
                        if inherits:
                            existing = collected_targets.setdefault(preset_type, [])
                            for i in inherits:
                                if i not in existing:
                                    existing.append(i)

        return collected_targets

    @staticmethod
    def _append_user_preset_path(data: Any, preset_path: Any, output_dir: str) -> dict[str, Any]:
        """ - Appends a 'include' to preset_path if the schema supports it.
            - Otherwise it merges to "data" all the configurePresets, buildPresets etc from the
              read preset_path.
        """
        if "include" not in data:
            data["include"] = []
        # Clear the folders that have been deleted
        data["include"] = [i for i in data.get("include", []) if os.path.exists(os.path.join(output_dir, i))]
        if preset_path not in data["include"]:
            data["include"].append(preset_path)
        return data


def load_cmake_presets(folder: str) -> dict[str, Any]:
    try:
        tmp = load(os.path.join(folder, "CMakePresets.json"))
    except FileNotFoundError:
        # Issue: upstream issue 12896
        raise RecipeException(
            f"CMakePresets.json was not found in {folder} folder. Check that you "
            f"are using CMakeToolchain as generator to ensure its correct "
            f"initialization.")
    return json.loads(tmp)
